using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using System.Linq;using System.Collections.Generic;using System.IO;
internal class CommandScript:IRunCommand {
 const float step=.15f,x0=-17.1f,z0=25.15f; const int nx=90,nz=154;
 bool[,] Walk(){var a=new bool[nx,nz];for(int x=0;x<nx;x++)for(int z=0;z<nz;z++){var p=new Vector3(x0+x*step,0,z0+z*step);a[x,z]=Physics.Raycast(p+Vector3.up*.08f,Vector3.down,.35f,~0,QueryTriggerInteraction.Ignore)&&!Physics.CheckCapsule(p+Vector3.up*.35f,p+Vector3.up*1.5f,.29f,~0,QueryTriggerInteraction.Ignore);}return a;}
 bool Reach(bool[,] a,Vector2 to){int sx=Mathf.RoundToInt((-5.7f-x0)/step),sz=Mathf.RoundToInt((27.8f-z0)/step),tx=Mathf.RoundToInt((to.x-x0)/step),tz=Mathf.RoundToInt((to.y-z0)/step);var seen=new bool[nx,nz];var q=new Queue<Vector2Int>();q.Enqueue(new Vector2Int(sx,sz));seen[sx,sz]=true;while(q.Count>0){var p=q.Dequeue();if(p.x==tx&&p.y==tz)return true;foreach(var d in new[]{Vector2Int.up,Vector2Int.down,Vector2Int.left,Vector2Int.right}){var n=p+d;if(n.x<0||n.y<0||n.x>=nx||n.y>=nz||seen[n.x,n.y]||!a[n.x,n.y])continue;seen[n.x,n.y]=true;q.Enqueue(n);}}return false;}
 public void Execute(ExecutionResult result){var all=Resources.FindObjectsOfTypeAll<Transform>().Where(t=>t.gameObject.scene==SceneManager.GetActiveScene()).ToArray();var hub=all.First(t=>t.name=="R1 Clinical Observation Hub").gameObject;bool active=hub.activeSelf;hub.SetActive(true);var gates=new[]{"R2 Anchor gallery access solid panel","P3 Gate A alternative route solid panel","P3 Gate B final hold solid panel"}.Select(n=>all.First(t=>t.name==n)).ToArray();var poses=gates.Select(t=>t.position).ToArray();var lines=new List<string>();
 Physics.SyncTransforms();lines.Add((!Reach(Walk(),new Vector2(-7.8f,35.2f))?"PASS":"FAIL")+" pre-anchor gallery access closed");
 gates[0].position+=Vector3.up*3.05f;Physics.SyncTransforms();var map=Walk();lines.Add((Reach(map,new Vector2(-7.8f,43))&&!Reach(map,new Vector2(-5.05f,39.5f))&&!Reach(map,new Vector2(-5.05f,46))?"PASS":"FAIL")+" recording lane reachable; closed A blocks alternative and payoff");
 gates[1].position+=Vector3.up*3.05f;Physics.SyncTransforms();map=Walk();lines.Add((Reach(map,new Vector2(-5.05f,39.5f))&&!Reach(map,new Vector2(-5.05f,46))?"PASS":"FAIL")+" open A permits alternative; closed B prevents payoff and lane bypass");
 gates[2].position+=Vector3.up*3.05f;Physics.SyncTransforms();map=Walk();lines.Add((Reach(map,new Vector2(-15.5f,46.3f))?"PASS":"FAIL")+" open A+B permits full payoff route");
 for(int i=0;i<3;i++)gates[i].position=poses[i];hub.SetActive(active);Physics.SyncTransforms();File.WriteAllLines("/tmp/echo-vs1-r2/topology.txt",lines);result.Log(string.Join("\n",lines));}
}
